def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    output = []
    i = 0
    n = len(template)
    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                output.append('{')
                i += 2
            else:
                # opening placeholder
                j = i + 1
                if j < n and template[j] == '}':
                    raise ValueError("empty placeholder at position " + str(i))
                name_chars = []
                while j < n and (template[j].isalnum() or template[j] == '_'):
                    # Actually, isalnum() includes letters and digits, but also other Unicode alphanumeric? 
                    # The spec says [A-Za-z0-9_]. So we should restrict to ASCII.
                    # Better to check explicitly: ('A' <= template[j] <= 'Z') or ('a' <= template[j] <= 'z') or ('0' <= template[j] <= '9') or template[j] == '_'
                    name_chars.append(template[j])
                    j += 1
                if j >= n:
                    raise ValueError("unclosed placeholder at position " + str(i))
                if template[j] != '}':
                    raise ValueError("invalid placeholder at position " + str(i))
                name = ''.join(name_chars)
                if name not in context:
                    raise KeyError(name)
                output.append(str(context[name]))
                i = j + 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                output.append('}')
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            output.append(c)
            i += 1
    return ''.join(output)

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")

    def _is_valid_index(s):
        if s.startswith('-'):
            body = s[1:]
            return body != "" and set(body) <= set("0123456789")
        else:
            return s != "" and set(s) <= set("0123456789")

    def _descend(node, segs):
        if not segs:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return _descend(node[seg], rest)
        elif isinstance(node, list):
            if not _is_valid_index(seg):
                raise ValueError("invalid index")
            idx = int(seg)
            try:
                next_node = node[idx]
            except IndexError:
                raise IndexError(seg)
            return _descend(next_node, rest)
        else:
            raise TypeError("cannot descend")

    return _descend(data, segments)

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError("Invalid lo/hi bounds")

    # Build prefix mod groups
    groups = {}
    mod = 0
    groups[mod] = [0]
    for i, d in enumerate(deltas, start=1):
        mod = (mod + d) % k
        if mod in groups:
            groups[mod].append(i)
        else:
            groups[mod] = [i]

    total = 0
    for indices in groups.values():
        # indices is sorted ascending
        L = 0
        R = 0
        m = len(indices)
        for i in indices:
            # We want j in indices such that lo <= j - i <= hi
            # Since indices sorted, we can maintain window [L, R)
            # Move R to include all j <= i + hi
            while R < m and indices[R] <= i + hi:
                R += 1
            # Move L to exclude j < i + lo
            while L < m and indices[L] < i + lo:
                L += 1
            # Count elements in [L, R)
            total += (R - L)
    return total

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    stack = []
    operators = {"+", "-", "*", "/"}

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i}")

        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:  # token == "/"
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                # Truncated toward zero (C-style), not Python floor division
                if (left < 0) != (right < 0):
                    stack.append(-(-left // right))
                else:
                    stack.append(left // right)
        else:
            # Validate operand literal: optional single leading + or - then digits
            if token == "":
                raise ValueError(f"unknown token at token {i}")
            if token[0] in "+-":
                if len(token) == 1 or not all(c in "0123456789" for c in token[1:]):
                    raise ValueError(f"unknown token at token {i}")
            else:
                if not all(c in "0123456789" for c in token):
                    raise ValueError(f"unknown token at token {i}")
            stack.append(int(token))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    if not data:
        return [0] * len(queries)
    N = len(data)
    bit = [0] * (N + 2)

    def bit_add(idx: int, val: int) -> None:
        while idx <= N + 1:
            bit[idx] += val
            idx += idx & -idx

    def bit_range_add(l: int, r: int, val: int) -> None:
        bit_add(l + 1, val)
        bit_add(r + 2, -val)

    def bit_point_query(idx: int) -> int:
        res = 0
        i = idx + 1
        while i > 0:
            res += bit[i]
            i -= i & -i
        return res

    queries_by_r = [[] for _ in range(N + 1)]
    ans = [0] * len(queries)
    for i, (l, r) in enumerate(queries):
        if r > 0:
            queries_by_r[r].append((l, i))
        # else ans[i] remains 0

    last_occ = {}
    for i in range(N):
        x = data[i]
        if x in last_occ:
            occ = last_occ[x]
            if len(occ) == 1:
                prev1 = occ[0]
                bit_range_add(0, prev1, 1)
                occ.append(i)
            else:
                prev2, prev1 = occ[0], occ[1]
                bit_range_add(0, prev2, -1)
                bit_range_add(0, prev1, 1)
                occ[0] = prev1
                occ[1] = i
        else:
            last_occ[x] = [i]

        for l, idx in queries_by_r[i + 1]:
            ans[idx] = bit_point_query(l)

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        # a. must be a tuple of length 3
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i} must be a tuple of length 3")

        category, amount, refunded = row

        # b. category must be a non-empty str
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i} has invalid category")

        # c. amount must be int or float, but not bool
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i} has invalid amount type")

        # d. amount must be >= 0
        if amount < 0:
            raise ValueError(f"row {i} has negative amount")

        # e. refunded must be a bool
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} has invalid refunded type")

        # Update summary
        if category not in result:
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": 0.0,
            }
        summary = result[category]
        summary["count"] += 1
        summary["gross"] += float(amount)
        if not refunded:
            summary["net"] += float(amount)
        if float(amount) > summary["largest"]:
            summary["largest"] = float(amount)

    return result

def top_k_frequent(items, k):
    # Validation 1: items must be a list
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    # Validation 2: k must be an int (and not a bool)
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    # Validation 3: k must be >= 0
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0:
        return []

    # Count frequencies and record first occurrence index
    counts = {}
    first_index = {}
    for i, item in enumerate(items):
        if item not in counts:
            counts[item] = 0
            first_index[item] = i
        counts[item] += 1

    # List of distinct values to select from
    remaining = list(counts.keys())
    result = []

    # Repeatedly select the best remaining value
    while k > 0 and remaining:
        best_val = remaining[0]
        best_count = counts[best_val]
        best_idx = first_index[best_val]

        for val in remaining[1:]:
            c = counts[val]
            idx = first_index[val]
            # Higher count wins; tie broken by smaller first index
            if c > best_count or (c == best_count and idx < best_idx):
                best_val = val
                best_count = c
                best_idx = idx

        result.append((best_val, best_count))
        remaining.remove(best_val)
        k -= 1

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [(iter(nested), 0)]

    while stack:
        it, depth = stack[-1]
        try:
            item = next(it)
        except StopIteration:
            stack.pop()
            continue

        if isinstance(item, list) and depth < max_depth:
            stack.append((iter(item), depth + 1))
        else:
            result.append(item)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text or text.isspace():
        raise ValueError("empty duration")

    i = 0
    n = len(text)
    digits = []
    last_unit_idx = -1
    total_seconds = 0
    component_count = 0

    while i < n:
        c = text[i]
        if c.isdigit():
            digits.append(c)
            i += 1
        else:
            if not digits:
                raise ValueError("malformed duration")
            if c not in ('h', 'm', 's'):
                raise ValueError("malformed duration")
            unit_idx = {'h': 0, 'm': 1, 's': 2}[c]
            if unit_idx <= last_unit_idx:
                raise ValueError("malformed duration")
            last_unit_idx = unit_idx
            value = int(''.join(digits))
            if c == 'h':
                total_seconds += value * 3600
            elif c == 'm':
                total_seconds += value * 60
            else:
                total_seconds += value
            component_count += 1
            digits = []
            i += 1

    if digits:
        raise ValueError("malformed duration")
    if component_count == 0:
        raise ValueError("malformed duration")

    return total_seconds

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(low, bool) or isinstance(high, bool) or not isinstance(low, (int, float)) or not isinstance(high, (int, float)):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    result = []
    for i, x in enumerate(values):
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"index {i}")
        if x < low:
            result.append(low)
        elif x > high:
            result.append(high)
        else:
            result.append(x)
    return result

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0

    # Sort jobs by bounty descending (greedy choice)
    jobs.sort(key=lambda x: x[1], reverse=True)

    # Disjoint-set structures for slots. Slot 0 is a sentinel with no capacity.
    parent = {0: 0}
    capacity = {0: 0}

    def find(x: int) -> int:
        """Find the latest available slot <= x, with path compression."""
        if x not in parent:
            parent[x] = x
            capacity[x] = cap
        # Find root
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while x != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    total = 0
    for d, p in jobs:
        r = find(d)
        if r == 0:
            continue  # no slot available
        capacity[r] -= 1
        total += p
        if capacity[r] == 0:
            # Slot r is full; link it to the previous slot
            parent[r] = find(r - 1)

    return total

def round_robin(iterables):
    iterators = [iter(it) for it in iterables]
    while iterators:
        next_iterators = []
        for it in iterators:
            try:
                val = next(it)
            except StopIteration:
                continue
            yield val
            next_iterators.append(it)
        iterators = next_iterators

import math

def vector_norm(v: list[float]) -> float:
    """Compute the Euclidean (L2) norm of a vector of floats robustly.

    Uses math.hypot to avoid overflow/underflow when squaring large or small
    values. Raises ValueError if any entry is NaN or infinite.
    """
    for x in v:
        if math.isinf(x) or math.isnan(x):
            raise ValueError("Vector contains inf or nan")
    norm = 0.0
    for x in v:
        norm = math.hypot(norm, x)
    return norm

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W <= 0:
        raise ValueError("sum of weights must be positive")

    # Sort pairs by value ascending
    pairs = sorted(zip(values, weights), key=lambda x: x[0])
    cumulative = 0.0
    threshold = W / 2.0 - 1e-9

    for value, weight in pairs:
        cumulative += weight
        if cumulative >= threshold:
            return value

    # Fallback (should never be reached when W > 0)
    return pairs[-1][0]

import bisect

class IntervalSet:
    def __init__(self):
        self._intervals = []  # list of [lo, hi] sorted by lo, disjoint, non-adjacent
        self._los = []        # list of lo values, kept in sync with _intervals

    def add(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        # Find the first interval that could overlap or touch [lo, hi)
        i = bisect.bisect_left(self._los, lo)
        start = i
        if i > 0 and self._intervals[i - 1][1] >= lo:
            start = i - 1
        # Scan forward to find all intervals that touch or overlap
        j = start
        while j < len(self._intervals) and self._intervals[j][0] <= hi:
            j += 1
        if start < j:
            new_lo = min(lo, self._intervals[start][0])
            new_hi = max(hi, self._intervals[j - 1][1])
            self._intervals[start:j] = [[new_lo, new_hi]]
            self._los[start:j] = [new_lo]
        else:
            self._intervals.insert(start, [lo, hi])
            self._los.insert(start, lo)

    def remove(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        # Find the first interval that could intersect [lo, hi)
        i = bisect.bisect_left(self._los, lo)
        start = i
        if i > 0 and self._intervals[i - 1][1] > lo:
            start = i - 1
        # Scan forward to find all intersecting intervals
        j = start
        while j < len(self._intervals) and self._intervals[j][0] < hi:
            j += 1
        new_intervals = []
        new_los = []
        for k in range(start, j):
            a, b = self._intervals[k]
            if a < lo:
                new_intervals.append([a, lo])
                new_los.append(a)
            if b > hi:
                new_intervals.append([hi, b])
                new_los.append(hi)
        self._intervals[start:j] = new_intervals
        self._los[start:j] = new_los

    def contains(self, x):
        i = bisect.bisect_right(self._los, x) - 1
        return i >= 0 and self._intervals[i][1] > x

    def total(self):
        return sum(hi - lo for lo, hi in self._intervals)

    def intervals(self):
        return [(lo, hi) for lo, hi in self._intervals]

    def gaps(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        # Find the first interval that could intersect [lo, hi)
        i = bisect.bisect_left(self._los, lo)
        start = i
        if i > 0 and self._intervals[i - 1][1] > lo:
            start = i - 1
        # Scan forward to find all intersecting intervals
        j = start
        while j < len(self._intervals) and self._intervals[j][0] < hi:
            j += 1
        gaps = []
        current = lo
        for k in range(start, j):
            a, b = self._intervals[k]
            if a > current:
                gaps.append((current, a))
            current = max(current, b)
        if current < hi:
            gaps.append((current, hi))
        return gaps

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    combining_categories = {'Mn', 'Mc', 'Me'}
    units = []
    current = None

    for ch in s:
        if unicodedata.category(ch) in combining_categories:
            if current is None:
                current = ch
            else:
                current += ch
        else:
            if current is not None:
                units.append(current)
            current = ch

    if current is not None:
        units.append(current)

    if width >= len(units):
        return s

    return ''.join(units[:width])

import heapq

class TaskScheduler:
    """A priority queue of unique task ids supporting reprioritization and cancellation.

    Higher priority is served first. Ties are broken by original submission order (FIFO).
    Reprioritizing a task does not change its FIFO position.
    """

    def __init__(self):
        # Min-heap of entries: (-priority, submission_order, task_id)
        self._heap = []
        # Maps active task_id -> (current_priority, submission_order)
        self._active = {}
        # Monotonic counter for FIFO ordering
        self._counter = 0

    def submit(self, task_id, priority):
        """Add a new active task. Raises ValueError if task_id is already active."""
        if task_id in self._active:
            raise ValueError(f"Task {task_id!r} is already active")
        order = self._counter
        self._counter += 1
        self._active[task_id] = (priority, order)
        heapq.heappush(self._heap, (-priority, order, task_id))

    def reprioritize(self, task_id, priority):
        """Change an active task's priority. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        old_priority, order = self._active[task_id]
        if old_priority == priority:
            return  # No change needed; old entry remains valid
        self._active[task_id] = (priority, order)
        heapq.heappush(self._heap, (-priority, order, task_id))

    def cancel(self, task_id):
        """Remove an active task without serving it. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        del self._active[task_id]

    def pop(self):
        """Remove and return the highest-priority task (ties: earliest submission).
        Raises IndexError if no tasks are active.
        """
        while self._heap:
            neg_priority, order, task_id = self._heap[0]
            # Check if this entry is the current one for the task
            if task_id in self._active and self._active[task_id][0] == -neg_priority:
                heapq.heappop(self._heap)
                del self._active[task_id]
                return task_id
            else:
                # Stale entry (old priority or cancelled task) – discard it
                heapq.heappop(self._heap)
        raise IndexError("pop from empty scheduler")

    def peek(self):
        """Return the highest-priority task without removing it.
        Raises IndexError if no tasks are active.
        """
        while self._heap:
            neg_priority, order, task_id = self._heap[0]
            if task_id in self._active and self._active[task_id][0] == -neg_priority:
                return task_id
            else:
                heapq.heappop(self._heap)  # clean up stale entry
        raise IndexError("peek from empty scheduler")

    def priority_of(self, task_id):
        """Return the current priority of an active task. Raises KeyError if not active."""
        if task_id not in self._active:
            raise KeyError(f"Task {task_id!r} is not active")
        return self._active[task_id][0]

    def __len__(self):
        """Return the number of active tasks."""
        return len(self._active)

from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _purge(self, now):
        """Remove all entries that are dead at `now`."""
        expired = []
        for key, (_, stored_time, ttl) in self.cache.items():
            if ttl is not None and now >= stored_time + ttl:
                expired.append(key)
        for key in expired:
            del self.cache[key]
            self.expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")
        self._purge(now)
        if key in self.cache:
            # Update existing entry and mark most-recently-used
            self.cache[key] = (value, now, ttl)
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                # Evict least-recently-used
                self.cache.popitem(last=False)
                self.evictions += 1
            self.cache[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self.cache:
            self.hits += 1
            self.cache.move_to_end(key)
            return self.cache[key][0]
        else:
            self.misses += 1
            return None

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }

    def __len__(self):
        return len(self.cache)

class VersionedKV:
    def __init__(self):
        self._working = {}
        self._history = []  # list of dict snapshots, index i corresponds to version i+1

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        self._history.append(dict(self._working))
        return len(self._history)

    def get_at(self, key, version):
        if not (1 <= version <= len(self._history)):
            raise ValueError(f"version {version} out of range")
        snapshot = self._history[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= len(self._history)):
            raise ValueError(f"version {version} out of range")
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._history[version - 1])

    def latest(self) -> int:
        return len(self._history)

class UndoStack:
    def __init__(self):
