        self._history = []

    def push(self, x) -> None:
        self._stack.append(x)
        self._history.append(('push',))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty stack")
        val = self._stack.pop()
        self._history.append(('pop', val))
        return val

    def peek(self):
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op = self._history.pop()
        if op[0] == 'push':
            self._stack.pop()
        else:  # 'pop'
            self._stack.append(op[1])

    def __len__(self) -> int:
        return len(self._stack)

from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R-1][C-1] == -1:
        return -1
    if R == 1 and C == 1:
        return 0

    # BFS from start
    dist_start = [[-1]*C for _ in range(R)]
    dist_start[0][0] = 0
    q = deque([(0, 0)])
    while q:
        r, col = q.popleft()
        d = dist_start[r][col]
        for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
            nr, nc = r+dr, col+dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist_start[nr][nc] == -1:
                dist_start[nr][nc] = d + 1
                q.append((nr, nc))

    # BFS from target
    dist_target = [[-1]*C for _ in range(R)]
    dist_target[R-1][C-1] = 0
    q = deque([(R-1, C-1)])
    while q:
        r, col = q.popleft()
        d = dist_target[r][col]
        for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
            nr, nc = r+dr, col+dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist_target[nr][nc] == -1:
                dist_target[nr][nc] = d + 1
                q.append((nr, nc))

    walk_cost = dist_start[R-1][C-1]
    if walk_cost == -1:
        walk_cost = float('inf')

    start_stats = {}
    target_stats = {}

    def update(stats, label, d, r, c):
        if label not in stats:
            stats[label] = [d, r, c, float('inf')]
        else:
            min_d, min_r, min_c, second_d = stats[label]
            if d < min_d:
                second_d = min_d
                min_d = d
                min_r, min_c = r, c
            elif d < second_d:
                second_d = d
            stats[label] = [min_d, min_r, min_c, second_d]

    for r in range(R):
        for col in range(C):
            if grid[r][col] == -1:
                continue
            label = grid[r][col]
            if dist_start[r][col] != -1:
                update(start_stats, label, dist_start[r][col], r, col)
            if dist_target[r][col] != -1:
                update(target_stats, label, dist_target[r][col], r, col)

    min_teleport = float('inf')
    for label, (s_min_d, s_min_r, s_min_c, s_second_d) in start_stats.items():
        if label in target_stats:
            t_min_d, t_min_r, t_min_c, t_second_d = target_stats[label]
            if s_min_d != float('inf') and t_min_d != float('inf'):
                if (s_min_r, s_min_c) != (t_min_r, t_min_c):
                    cost = s_min_d + t_min_d + c
                else:
                    cost = min(s_min_d + t_second_d, s_second_d + t_min_d) + c
                if cost < min_teleport:
                    min_teleport = cost

    ans = min(walk_cost, min_teleport)
    return ans if ans != float('inf') else -1

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)
    order = []
    visiting = set()

    def visit(node):
        if node in order:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        order.append(node)

    for node in sorted(graph):
        if node not in order:
            visit(node)
    return order

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

import re

def compute_balances(transactions):
    balances = {}
    amount_re = re.compile(r'^[0-9]+(\.[0-9]{1,2})?$')
    for tx in transactions:
        amount_str = tx["amount"]
        if not amount_re.match(amount_str):
            raise ValueError("invalid amount")
        if '.' in amount_str:
            int_part, frac_part = amount_str.split('.')
            if len(frac_part) == 1:
                cents = int(int_part) * 100 + int(frac_part) * 10
            else:
                cents = int(int_part) * 100 + int(frac_part)
        else:
            cents = int(amount_str) * 100
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def max_sessions(intervals, gap):
    if not intervals:
        return 0
    # Sort intervals by their end time.
    intervals.sort(key=lambda x: x[1])
    count = 0
    last_end = None
    for s, e in intervals:
        if last_end is None or s >= last_end + gap:
            count += 1
            last_end = e
    return count
